```

**3. `.claude/hooks/format-bash-changes.sh`** (after each Bash call)

```bash
#!/usr/bin/env bash
sid=$(jq -r '.session_id')
marker="${TMPDIR:-/tmp}/claude-bash-mark-$sid"
cd "$CLAUDE_PROJECT_DIR" || exit 0
[ -f "$marker" ] || exit 0

files=$(find . -type f -newer "$marker" \
  -not -path './.git/*' -not -path '*/node_modules/*' \
  \( -name '*.ts' -o -name '*.tsx' -o -name '*.js' -o -name '*.jsx' \
     -o -name '*.json' -o -name '*.md' -o -name '*.css' -o -name '*.yaml' -o -name '*.yml' \))
[ -n "$files" ] || exit 0

