#!/bin/sh
# PreToolUse gate for the Bash tool: block any rm that is recursive and forced
# (rm -rf, rm -fr, rm -r -f, rm -R --force, /bin/rm -rf, sudo rm -rf, sh -c "rm -rf ...").
# Exit 2 blocks the call; stderr is sent to Claude as the reason.
# Any other failure (crash, bad JSON) is treated as a block by onFailure in hooks.json.
exec python3 -I -c '
import json, shlex, re, sys

command = json.load(sys.stdin).get("tool_input", {}).get("command", "")

# Split into simple commands at shell separators, then into words at whitespace and quotes.
for segment in re.split(r"[;&|()`\n]", command):
    words = [w for w in re.split(r"[\s\"\x27\\\\{}]+", segment) if w]
    for i, word in enumerate(words):
        if word.rsplit("/", 1)[-1] != "rm":
            continue
        args = words[i + 1:]
        short = "".join(a[1:] for a in args if a.startswith("-") and not a.startswith("--"))
        long = [a for a in args if a.startswith("--")]
        recursive = "r" in short or "R" in short or "--recursive" in long
        force = "f" in short or "--force" in long
        if recursive and force:
            sys.stderr.write(
                "Blocked: rm -rf (recursive + force) is not allowed in this project.\n"
                "Remove the specific files with plain rm, or ask the user to run the deletion themselves.\n"
            )
            sys.exit(2)
'
EOF
