{
  "description": "Blocks recursive forced deletes (rm -rf) in Bash tool calls",
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          { "type": "command", "command": "sh \"${CLAUDE_PLUGIN_ROOT}/hooks/block-rm.sh\"", "timeout": 10, "onFailure": "block" }
        ]
      }
    ]
  }
}
EOF
