#!/bin/sh
# Stop gate: block Claude from finishing while `npm test` fails.
# Exit 2 + stderr = keep working on the failure; exit 0 = allow the stop.
# Fails closed: a missing jq or an unusable project directory blocks the stop.

command -v jq >/dev/null 2>&1 || { echo "stop-gate: jq is required" >&2; exit 2; }

input=$(cat)
dir=$(printf '%s' "$input" | jq -r '.cwd // empty')
[ -n "$dir" ] || dir="${CLAUDE_PROJECT_DIR:-$PWD}"
cd "$dir" || { echo "stop-gate: cannot cd to $dir" >&2; exit 2; }

# No package.json means no npm test to gate on.
[ -f package.json ] || exit 0

if out=$(npm test 2>&1); then
  exit 0
fi

{
  echo "npm test is failing - keep working until it passes. Last output:"
  printf '%s\n' "$out" | tail -n 60
} >&2
exit 2
EOF
